PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry groupnorm_kernel(
    .param .u64 src_ptr,
    .param .u64 dst_ptr,
    .param .u32 N,
    .param .u32 C,
    .param .u32 H,
    .param .u32 W,
    .param .u32 G
)
{
    // registers
    .reg .u64 %src, %dst;
    .reg .u32 %N, %C, %H, %W, %G;
    .reg .u32 %n, %g;
    .reg .u32 %tid, %blockIdxX, %blockIdxY;
    .reg .u32 %C_per_group, %elem_per_group, %HW;
    .reg .u32 %i, %idx, %offset;
    .reg .f32 %sum, %sumsq, %total, %total2, %mean, %var, %inv_std, %fval, %norm;
    .reg .f16 %hval;
    .reg .u64 %addr;
    .reg .pred %p, %p0;

    // load parameters
    ld.param.u64 %src, [src_ptr];
    ld.param.u64 %dst, [dst_ptr];
    ld.param.u32 %N,   [N];
    ld.param.u32 %C,   [C];
    ld.param.u32 %H,   [H];
    ld.param.u32 %W,   [W];
    ld.param.u32 %G,   [G];

    // thread / block indices
    mov.u32 %tid,      %tid.x;
    mov.u32 %blockIdxX,%ctaid.x;
    mov.u32 %blockIdxY,%ctaid.y;

    // n = batch index, g = group index
    mov.u32 %n, %blockIdxX;
    mov.u32 %g, %blockIdxY;

    // channels per group and elements per group
    div.u32 %C_per_group, %C, %G;
    mul.lo.u32 %HW, %H, %W;
    mul.lo.u32 %elem_per_group, %C_per_group, %HW;

    // group base offset (in elements): ((n*C) + (g*C_per_group)) * HW
    mul.lo.u32 %i, %n, %C;                // n*C
    mul.lo.u32 %idx, %g, %C_per_group;   // g*C_per_group
    add.u32 %i, %i, %idx;                // n*C + g*C_per_group
    mul.lo.u32 %i, %i, %HW;              // *HW   -> group_offset

    // ---- first pass: compute sum & sum of squares ----
    mov.f32 %sum,    0f0;
    mov.f32 %sumsq,  0f0;
    mov.u32 %offset, %tid;

LOOP_SUM:
    setp.ge.u32 %p, %offset, %elem_per_group;
    @%p bra END_LOOP_SUM;

    // element index = group_offset + offset
    add.u32 %idx, %i, %offset;           // idx (in elements)
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;             // byte offset (half = 2 bytes)
    add.u64 %addr, %src, %addr;

    ld.global.nc.f16 %hval, [%addr];
    cvt.f32.f16 %fval, %hval;
    add.f32 %sum, %sum, %fval;
    mul.f32 %norm, %fval, %fval;         // square
    add.f32 %sumsq, %sumsq, %norm;

    add.u32 %offset, %offset, 256;       // stride = blockDim.x
    bra LOOP_SUM;
END_LOOP_SUM:

    // shared memory for per‑thread partials
    .shared .align 4 .b8 shmem_sum[1024];
    .shared .align 4 .b8 shmem_sumsq[1024];

    mul.lo.u32 %idx, %tid, 4;            // byte offset for this thread
    st.shared.f32 [shmem_sum+%idx],   %sum;
    st.shared.f32 [shmem_sumsq+%idx], %sumsq;

    bar.sync 0;                          // ensure all writes visible

    // ---- reduction by thread 0 ----
    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        mov.f32 %total,  0f0;
        mov.f32 %total2, 0f0;
        mov.u32 %i, 0;
REDUCLP:
        setp.ge.u32 %p, %i, 256;
        @%p bra REDUCDONE;
        mul.lo.u32 %idx, %i, 4;
        ld.shared.f32 %fval, [shmem_sum+%idx];
        add.f32 %total, %total, %fval;
        ld.shared.f32 %fval, [shmem_sumsq+%idx];
        add.f32 %total2, %total2, %fval;
        add.u32 %i, %i, 1;
        bra REDUCLP;
REDUCDONE:
        // mean = total / N
        cvt.f32.u32 %norm, %elem_per_group;
        div.full.f32 %mean, %total, %norm;
        // var = (total2 / N) - mean^2
        div.full.f32 %var, %total2, %norm;
        mul.f32 %norm, %mean, %mean;
        sub.f32 %var, %var, %norm;

        // store mean & var for all threads
        st.shared.f32 [shmem_sum+0],   %mean;
        st.shared.f32 [shmem_sumsq+0], %var;
    }

    bar.sync 0;                          // broadcast mean/var

    ld.shared.f32 %mean, [shmem_sum+0];
    ld.shared.f32 %var,  [shmem_sumsq+0];

    // inv_std = rsqrt(var + eps)
    add.f32 %norm, %var, 1e-05;
    rsqrt.approx.f32 %inv_std, %norm;

    // ---- second pass: write normalized output ----
    mov.u32 %offset, %tid;

LOOP_NORM:
    setp.ge.u32 %p, %offset, %elem_per_group;
    @%p bra END_LOOP_NORM;

    add.u32 %idx, %i, %offset;           // element index
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %src, %addr;

    ld.global.nc.f16 %hval, [%addr];
    cvt.f32.f16 %fval, %hval;
    sub.f32 %norm, %fval, %mean;
    mul.f32 %norm, %norm, %inv_std;
    cvt.f16.f32 %hval, %norm;

    // destination address
    cvt.u64.u32 %addr, %idx;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %dst, %addr;
    st.global.nc.f16 [%addr], %hval;

    add.u32 %offset, %offset, 256;
    bra LOOP_NORM;
END_LOOP_NORM:

    ret;
}
'''

