# ----------------------------------------------------------------------
import torch

class ModelNew:
    """
    Drop‑in replacement for the reference GroupNorm model.
    Expects fp16 input tensor of shape (N, C, H, W) and returns a
    fp16 tensor of the same shape.
    """
    def __init__(self, features: int, num_groups: int):
        self.features = features
        self.num_groups = num_groups
        # Load PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be fp16"
        assert x.is_cuda, "Input must be on CUDA"
        N, C, H, W = x.shape
        y = torch.empty_like(x)

        # Grid: one block per (batch, group)
        grid = (N, self.num_groups, 1)
        block = (256, 1, 1)

        args = [
            x.data_ptr(),          # src_ptr
            y.data_ptr(),          # dst_ptr
            N, C, H, W, self.num_groups
        ]

        ptx_launch(self.module, "groupnorm_kernel", grid, block, args)
        return y
